#!/usr/bin/env python3
import json
import pdfplumber
import pandas as pd
from openpyxl import load_workbook

def extract_pdf_data(pdf_path):
    """Extract employee data from PDF file"""
    employees = {}

    with pdfplumber.open(pdf_path) as pdf:
        for page in pdf.pages:
            tables = page.extract_tables()
            for table in tables:
                if not table:
                    continue

                # Find header row
                header_idx = None
                for i, row in enumerate(table):
                    if row and any('ID' in str(cell) or 'Employee' in str(cell) for cell in row if cell):
                        header_idx = i
                        break

                if header_idx is None:
                    continue

                headers = [str(h).strip() if h else '' for h in table[header_idx]]

                # Process data rows
                for row in table[header_idx + 1:]:
                    if not row or not any(row):
                        continue

                    # Create employee record
                    record = {}
                    for i, value in enumerate(row):
                        if i < len(headers) and headers[i]:
                            if value:
                                record[headers[i]] = str(value).strip()

                    # Get employee ID
                    emp_id = None
                    for key in record:
                        if 'ID' in key.upper() or 'EMPLOYEE' in key.upper():
                            emp_id = record[key]
                            break

                    if emp_id and emp_id.startswith('EMP'):
                        employees[emp_id] = record

    return employees

def extract_excel_data(excel_path):
    """Extract employee data from Excel file"""
    employees = {}

    df = pd.read_excel(excel_path)

    # Find ID column
    id_col = None
    for col in df.columns:
        if 'ID' in str(col).upper() or 'EMPLOYEE' in str(col).upper():
            id_col = col
            break

    if not id_col:
        return employees

    for _, row in df.iterrows():
        emp_id = str(row[id_col]).strip()
        if emp_id.startswith('EMP'):
            record = {}
            for col in df.columns:
                value = row[col]
                if pd.notna(value):
                    record[str(col)] = value
            employees[emp_id] = record

    return employees

def normalize_field_name(field):
    """Normalize field names for comparison"""
    return field.strip().lower().replace(' ', '').replace('_', '')

def normalize_value(value):
    """Normalize values for comparison"""
    if isinstance(value, str):
        # Try to convert to number if possible
        try:
            if '.' in value:
                return float(value)
            else:
                return int(value)
        except ValueError:
            return value.strip()
    return value

def compare_employees(pdf_employees, excel_employees):
    """Compare old PDF data with current Excel data"""
    deleted_employees = []
    modified_employees = []

    # Find deleted employees
    for emp_id in pdf_employees:
        if emp_id not in excel_employees:
            deleted_employees.append(emp_id)

    # Find modified employees
    for emp_id in pdf_employees:
        if emp_id in excel_employees:
            old_record = pdf_employees[emp_id]
            new_record = excel_employees[emp_id]

            # Create field mapping (normalized)
            old_fields = {normalize_field_name(k): (k, v) for k, v in old_record.items()}
            new_fields = {normalize_field_name(k): (k, v) for k, v in new_record.items()}

            # Compare fields
            for norm_field, (old_field, old_val) in old_fields.items():
                if norm_field in new_fields:
                    new_field, new_val = new_fields[norm_field]

                    # Normalize values for comparison
                    old_normalized = normalize_value(old_val)
                    new_normalized = normalize_value(new_val)

                    if old_normalized != new_normalized:
                        modified_employees.append({
                            "id": emp_id,
                            "field": new_field,  # Use the field name from the new data
                            "old_value": old_normalized,
                            "new_value": new_normalized
                        })

    # Sort by ID
    deleted_employees.sort()
    modified_employees.sort(key=lambda x: x['id'])

    return {
        "deleted_employees": deleted_employees,
        "modified_employees": modified_employees
    }

def main():
    pdf_path = '/root/employees_backup.pdf'
    excel_path = '/root/employees_current.xlsx'
    output_path = '/root/diff_report.json'

    print("Extracting data from PDF...")
    pdf_employees = extract_pdf_data(pdf_path)
    print(f"Found {len(pdf_employees)} employees in PDF")

    print("Extracting data from Excel...")
    excel_employees = extract_excel_data(excel_path)
    print(f"Found {len(excel_employees)} employees in Excel")

    print("Comparing data...")
    diff_report = compare_employees(pdf_employees, excel_employees)

    print(f"Deleted employees: {len(diff_report['deleted_employees'])}")
    print(f"Modified employees: {len(diff_report['modified_employees'])}")

    # Write report
    with open(output_path, 'w') as f:
        json.dump(diff_report, f, indent=2)

    print(f"\nReport written to {output_path}")

if __name__ == '__main__':
    main()

