#!/usr/bin/env python3
import json
import pdfplumber
import pandas as pd

def parse_value(value):
    """Parse and normalize a value from string"""
    if not isinstance(value, str):
        return value

    value = value.strip()

    # Remove commas from numbers
    if ',' in value:
        value = value.replace(',', '')

    # Try to convert to number
    try:
        if '.' in value:
            return float(value)
        else:
            return int(value)
    except ValueError:
        return value

def extract_pdf_data(pdf_path):
    """Extract employee data from PDF file"""
    employees = {}

    # Expected column names based on the structure
    expected_headers = ['ID', 'First', 'Last', 'Dept', 'Position', 'Salary', 'Years', 'Location', 'Score']

    with pdfplumber.open(pdf_path) as pdf:
        for page in pdf.pages:
            tables = page.extract_tables()
            for table in tables:
                if not table:
                    continue

                # Check if first row is a header row
                first_row = [str(cell).strip() if cell else '' for cell in table[0]]
                if 'ID' in first_row or 'First' in first_row:
                    # This is a header row
                    headers = first_row
                    start_idx = 1
                else:
                    # No header row, use expected headers
                    headers = expected_headers
                    start_idx = 0

                # Process data rows
                for row in table[start_idx:]:
                    if not row or not any(row):
                        continue

                    emp_id = row[0].strip() if row[0] else None
                    if not emp_id or not emp_id.startswith('EMP'):
                        continue

                    record = {}
                    for i, value in enumerate(row):
                        if i < len(headers) and headers[i] and value:
                            record[headers[i]] = parse_value(value)

                    employees[emp_id] = record

    return employees

def extract_excel_data(excel_path):
    """Extract employee data from Excel file"""
    employees = {}
    df = pd.read_excel(excel_path)

    for _, row in df.iterrows():
        emp_id = str(row['ID']).strip()
        if not emp_id.startswith('EMP'):
            continue

        record = {}
        for col in df.columns:
            value = row[col]
            if pd.notna(value):
                # Parse string values, keep numbers as is
                if isinstance(value, str):
                    record[col] = parse_value(value)
                else:
                    record[col] = value

        employees[emp_id] = record

    return employees

def compare_employees(pdf_employees, excel_employees):
    """Compare old PDF data with current Excel data"""
    deleted_employees = []
    modified_employees = []

    # Find deleted employees (in PDF but not in Excel)
    for emp_id in pdf_employees:
        if emp_id not in excel_employees:
            deleted_employees.append(emp_id)

    # Find modified employees
    for emp_id in pdf_employees:
        if emp_id not in excel_employees:
            continue  # Already counted as deleted

        old_record = pdf_employees[emp_id]
        new_record = excel_employees[emp_id]

        # Compare each field
        for field in old_record:
            if field not in new_record:
                continue  # Field doesn't exist in new record

            old_val = old_record[field]
            new_val = new_record[field]

            # Handle floating point comparison
            if isinstance(old_val, float) and isinstance(new_val, float):
                if abs(old_val - new_val) > 0.001:
                    modified_employees.append({
                        "id": emp_id,
                        "field": field,
                        "old_value": old_val,
                        "new_value": new_val
                    })
            elif old_val != new_val:
                modified_employees.append({
                    "id": emp_id,
                    "field": field,
                    "old_value": old_val,
                    "new_value": new_val
                })

    # Sort by ID, then by field for consistent ordering
    deleted_employees.sort()
    modified_employees.sort(key=lambda x: (x['id'], x['field']))

    return {
        "deleted_employees": deleted_employees,
        "modified_employees": modified_employees
    }

def main():
    pdf_path = '/root/employees_backup.pdf'
    excel_path = '/root/employees_current.xlsx'
    output_path = '/root/diff_report.json'

    print("Extracting data from PDF...")
    pdf_employees = extract_pdf_data(pdf_path)
    print(f"Found {len(pdf_employees)} employees in PDF")

    print("Extracting data from Excel...")
    excel_employees = extract_excel_data(excel_path)
    print(f"Found {len(excel_employees)} employees in Excel")

    print("Comparing data...")
    diff_report = compare_employees(pdf_employees, excel_employees)

    print(f"\nDeleted employees: {len(diff_report['deleted_employees'])}")
    print(f"Modified employees: {len(diff_report['modified_employees'])}")

    if diff_report['deleted_employees']:
        print(f"Deleted IDs (first 10): {diff_report['deleted_employees'][:10]}")

    if diff_report['modified_employees']:
        print(f"Sample modifications (first 3):")
        for mod in diff_report['modified_employees'][:3]:
            print(f"  {mod}")

    # Write report
    with open(output_path, 'w') as f:
        json.dump(diff_report, f, indent=2)

    print(f"\nReport written to {output_path}")

if __name__ == '__main__':
    main()

